44	<script>
45	const SAMPLE_SYLLABUS = `《数据库系统原理》2026 秋 期末考试范围
46	1. 关系模型与关系代数
47	2. SQL 查询与视图
48	3. 索引：B+树与哈希索引
49	4. 函数依赖与范式（3NF、BCNF）
50	5. 查询处理与优化
51	6. 事务的 ACID 特性
52	7. 并发控制：两阶段锁与死锁
53	8. 隔离级别与 MVCC
54	9. 故障恢复：WAL 与 ARIES
55	10. 分布式事务与两阶段提交（2PC）`;
56	
57	function getSourceHeader() {
58	  const params = new URLSearchParams(window.location.search);
59	  return params.get('source') === 'auto' ? 'auto' : 'real';
60	}
61	
62	function loadSample() {
63	  document.getElementById('syllabus-input').value = SAMPLE_SYLLABUS;
64	}
