66	async function loadLatest() {
67	  const cid = document.getElementById('course-id').value;
68	  const status = document.getElementById('analyze-status');
69	  try {
70	    const r = await fetch(`/api/coverage/latest?course_id=${encodeURIComponent(cid)}`);
71	    if (!r.ok) { status.innerHTML = '<span style="color:#888">没有找到历史分析记录</span>'; return; }
72	    const d = await r.json();
73	    document.getElementById('syllabus-input').value = d.topics.map((t, i) => `${i+1}. ${t.name}`).join('\n');
74	    renderResults(d);
75	  } catch(e) {
76	    status.innerHTML = '<span style="color:red">加载失败</span>';
77	  }
78	}
79	
80	async function doAnalyze() {
81	  const btn = document.getElementById('analyze-btn');
82	  const status = document.getElementById('analyze-status');
83	  const area = document.getElementById('results-area');
84	  const text = document.getElementById('syllabus-input').value.trim();
85	  if (!text) { status.innerHTML = '<span style="color:red">请先粘贴考试范围</span>'; return; }
86	  btn.disabled = true;
87	  btn.textContent = '分析中...';
88	  status.innerHTML = '';
89	  area.innerHTML = '';
90	  try {
91	    const headers = {'Content-Type': 'application/json'};
92	    if (getSourceHeader() === 'auto') headers['X-ExamRadar-Source'] = 'auto';
93	    const r = await fetch('/api/coverage/analyze', {
94	      method: 'POST', headers,
95	      body: JSON.stringify({
96	        course_id: document.getElementById('course-id').value,
97	        syllabus_text: text,
98	      })
99	    });
100	    const d = await r.json();
101	    if (!r.ok) { status.innerHTML = '<span style="color:red">分析失败: ' + escapeHtml(d.detail || '') + '</span>'; return; }
102	    renderResults(d);
103	  } catch(err) {
104	    status.innerHTML = '<span style="color:red">分析失败: ' + escapeHtml(err.message) + '</span>';
105	  }
106	  btn.disabled = false;
107	  btn.textContent = '开始分析';
108	}
109	
110	function renderResults(data) {
111	  const area = document.getElementById('results-area');
112	  const items = data.items || [];
113	  if (!items.length) { area.innerHTML = '<div class="card"><p>没有分析结果</p></div>'; return; }
114	
115	  let html = '';
116	
117	  html += '<div class="card"><h2>覆盖度雷达图</h2><div id="radar-chart" style="width:100%;height:450px"></div></div>';
118	
119	  html += '<div class="card"><h2>盲区清单（按 考试权重 × 未覆盖度 排序）</h2>';
120	  html += '<table><tr><th>排名</th><th>知识点</th><th>覆盖度</th><th>考试权重</th><th>盲区分数</th><th>判定理由</th></tr>';
121	  items.forEach((item, i) => {
122	    const levelClass = item.coverage_level === 'covered' ? 'level-covered' :
123	                       item.coverage_level === 'thin' ? 'level-thin' : 'level-missing';
124	    html += `<tr>
125	      <td>${i+1}</td>
126	      <td><strong>${escapeHtml(item.topic_id)}</strong> ${escapeHtml(item.topic_name)}</td>
127	      <td><span class="${levelClass}">${item.coverage_level}</span> (${(item.coverage_score * 100).toFixed(1)}%)</td>
128	      <td>${item.exam_weight} 分</td>
129	      <td>${item.blind_spot_score.toFixed(2)}</td>
130	      <td><details><summary>查看理由</summary><p style="margin:8px 0;font-size:13px;color:#555">${escapeHtml(item.reason)}</p></details></td>
131	    </tr>`;
132	  });
133	  html += '</table></div>';
134	
135	  items.forEach((item, i) => {
136	    html += `<div class="card"><h2>${escapeHtml(item.topic_id)} · ${escapeHtml(item.topic_name)}</h2>`;
137	    html += `<p><strong>覆盖度：</strong><span class="${item.coverage_level === 'covered' ? 'level-covered' : item.coverage_level === 'thin' ? 'level-thin' : 'level-missing'}">${item.coverage_level}</span> (${(item.coverage_score * 100).toFixed(1)}%)</p>`;
138	    html += `<p><strong>考试权重：</strong>${item.exam_weight} 分</p>`;
139	    html += `<p><strong>判定理由：</strong>${escapeHtml(item.reason)}</p>`;
140	
141	    if (item.keywords && item.keywords.length) {
142	      html += `<p><strong>关键词/别名：</strong>${item.keywords.map(k => escapeHtml(k)).join('、')}</p>`;
143	    }
144	
145	    if (item.best_evidence) {
146	      const ev = item.best_evidence;
147	      html += '<details open><summary><strong>最强证据</strong></summary>';
148	      html += `<div style="margin:8px 0;padding:8px;background:#f8f9fa;border-radius:6px">`;
149	      html += `<div style="font-size:12px;color:#888">`;
150	      if (ev.document_name) html += escapeHtml(ev.document_name);
151	      if (ev.page) html += ` · 第${ev.page}页`;
152	      if (ev.heading) html += ` · ${escapeHtml(ev.heading)}`;
153	      html += `</div>`;
154	      html += `<div style="font-size:13px;margin-top:4px;white-space:pre-wrap">${escapeHtml((ev.content || '').substring(0, 300))}${(ev.content || '').length > 300 ? '...' : ''}</div>`;
155	      html += `<div style="font-size:12px;color:#666;margin-top:4px">语义分: ${fmtScore(ev.semantic_score, 4)} | 关键词分: ${fmtScore(ev.keyword_score, 2)}</div>`;
156	      html += `</div></details>`;
157	    }
158	
159	    if (item.exam_questions && item.exam_questions.length) {
160	      html += '<details><summary><strong>关联试题</strong></summary>';
161	      html += '<table style="margin-top:8px"><tr><th>题号</th><th>分值</th><th>相似度</th></tr>';
162	      item.exam_questions.forEach(q => {
163	        html += `<tr><td>第${q.question_no}题</td><td>${q.points}分</td><td>${(q.similarity * 100).toFixed(1)}%</td></tr>`;
164	      });
165	      html += '</table></details>';
166	    }
167	
168	    if (item.all_evidence && item.all_evidence.length > 1) {
169	      html += '<details><summary><strong>全部证据（' + item.all_evidence.length + ' 条）</strong></summary>';
170	      item.all_evidence.forEach((ev, j) => {
171	        html += `<div style="margin:8px 0;padding:8px;background:#f8f9fa;border-radius:6px">`;
172	        html += `<div style="font-size:12px;color:#888">#${j+1} `;
173	        if (ev.document_name) html += escapeHtml(ev.document_name);
174	        if (ev.page) html += ` · 第${ev.page}页`;
175	        if (ev.heading) html += ` · ${escapeHtml(ev.heading)}`;
176	        html += `</div>`;
177	        html += `<div style="font-size:12px;color:#666;margin-top:2px">语义分: ${fmtScore(ev.semantic_score, 4)} | 关键词分: ${fmtScore(ev.keyword_score, 2)}</div>`;
178	        html += `</div>`;
179	      });
180	      html += '</details>';
181	    }
182	
183	    html += '</div>';
184	  });
185	
186	  area.innerHTML = html;
187	
188	  renderRadarChart(items);
