190	
191	function renderRadarChart(items) {
192	  const chart = echarts.init(document.getElementById('radar-chart'));
193	  const maxWeight = Math.max(...items.map(i => i.exam_weight), 1);
194	  const indicators = items.map(i => ({
195	    name: i.topic_id + ' ' + i.topic_name.substring(0, 8),
196	    max: 1.0,
197	  }));
198	  const coverageData = items.map(i => i.coverage_score);
199	  const weightData = items.map(i => i.exam_weight / maxWeight);
200	
201	  chart.setOption({
202	    tooltip: {},
203	    legend: { data: ['覆盖度', '考试权重'], bottom: 0 },
204	    radar: {
205	      indicator: indicators,
206	      shape: 'polygon',
207	      splitArea: { areaStyle: { color: ['#fff', '#f5f6fa'] } },
208	    },
209	    series: [{
210	      type: 'radar',
211	      data: [
212	        { value: coverageData, name: '覆盖度', areaStyle: { opacity: 0.15 }, lineStyle: { color: '#0b4f8a' }, itemStyle: { color: '#0b4f8a' } },
213	        { value: weightData, name: '考试权重', areaStyle: { opacity: 0.1 }, lineStyle: { color: '#e67e22', type: 'dashed' }, itemStyle: { color: '#e67e22' } },
214	      ],
215	    }],
216	  });
217	  window.addEventListener('resize', () => chart.resize());
218	}
219	
220	function fmtScore(v, digits) {
221	  return (v === null || v === undefined) ? '—' : Number(v).toFixed(digits);
222	}
223	function escapeHtml(s) { const d = document.createElement('div'); d.textContent = s == null ? '' : s; return d.innerHTML; }
224	</script>
225	</body>
226	</html>
