38	<textarea id="query-input" rows="2" placeholder="例如：B+树插入时结点怎么分裂？"></textarea>
39	<button class="btn" style="margin-top:12px" id="search-btn" onclick="doSearch()">检索</button>
40	</div>
41	<div id="results-area"></div>
42	</div>
43	<!-- marked v15.0.12 (MIT), vendored from https://cdn.jsdelivr.net/npm/marked@15.0.12/marked.min.js -->
44	<script src="/static/lib/marked.min.js"></script>
45	<script>
46	const SHOW_FIRST = 5;
47	
48	function getSourceHeader() {
49	  const params = new URLSearchParams(window.location.search);
50	  return params.get('source') === 'auto' ? 'auto' : null;
51	}
52	
53	function sourceLine(item) {
54	  const parts = [];
55	  if (item.document_name) parts.push(item.document_name);
56	  if (item.page) parts.push('第' + item.page + '页');
57	  if (item.question_no) parts.push('第' + item.question_no + '题' + (item.points ? ' (' + item.points + '分)' : ''));
58	  if (item.heading) parts.push(item.heading);
59	  return parts.join(' · ');
60	}
61	
62	function fmtScore(v, digits) {
63	  return (v === null || v === undefined) ? '—' : Number(v).toFixed(digits);
64	}
65	
66	function renderContent(text) {
67	  return marked.parse(escapeHtml(text));
68	}
69	
70	function resultHtml(item) {
71	  return `<div class="result-item">
72	    <div class="meta">#${item.rank} ${escapeHtml(sourceLine(item))}</div>
73	    <div class="content md">${renderContent(item.content)}</div>
74	    <div class="scores">
75	      RRF: ${fmtScore(item.score, 4)} |
76	      关键词: ${fmtScore(item.keyword_score, 2)} (rank ${item.keyword_rank ?? '—'}) |
77	      语义: ${fmtScore(item.semantic_score, 4)} (rank ${item.semantic_rank ?? '—'})
78	    </div>
79	  </div>`;
80	}
81	
82	async function doSearch() {
83	  const btn = document.getElementById('search-btn');
84	  const area = document.getElementById('results-area');
85	  btn.disabled = true;
86	  btn.textContent = '检索中...';
87	  area.innerHTML = '';
88	  const query = document.getElementById('query-input').value.trim();
89	  if (!query) { area.innerHTML = '<div class="card"><p>请输入问题</p></div>'; btn.disabled = false; btn.textContent = '检索'; return; }
90	  try {
91	    const r = await fetch('/api/search', {
92	      method: 'POST',
93	      headers: Object.assign({'Content-Type': 'application/json'}, getSourceHeader() ? {'X-ExamRadar-Source': getSourceHeader()} : {}),
94	      body: JSON.stringify({
95	        query: query,
96	        course_id: document.getElementById('course-id').value,
97	        include_exam: document.getElementById('include-exam').checked,
98	        top_k: 10,
99	      })
100	    });
101	    const d = await r.json();
102	    if (!d.results || !d.results.length) {
103	      area.innerHTML = '<div class="card"><p>没有找到相关结果</p></div>';
104	      return;
105	    }
106	    let html = '<div class="card"><h2>检索结果</h2>';
107	    html += d.results.slice(0, SHOW_FIRST).map(resultHtml).join('');
108	    html += `<div id="more-results" style="display:none">` +
109	      d.results.slice(SHOW_FIRST).map(resultHtml).join('') + `</div>`;
110	    if (d.results.length > SHOW_FIRST) {
111	      html += `<button class="btn" style="width:100%" id="show-more-btn" onclick="showMore(this)">显示更多（${d.results.length - SHOW_FIRST} 条）</button>`;
112	    }
113	    html += '</div>';
114	    html += `<div class="card"><details><summary>seekdb 实际执行的检索 JSON</summary>
115	      <pre>${escapeHtml(JSON.stringify(d.search_json, null, 2))}</pre></details>
116	      <details><summary>GET_SQL 结果</summary><pre>${escapeHtml(d.actual_sql||'(空)')}</pre></details></div>`;
117	    area.innerHTML = html;
118	  } catch(err) {
119	    area.innerHTML = '<div class="card status err">检索失败: ' + escapeHtml(err.message) + '</div>';
120	  }
121	  btn.disabled = false;
122	  btn.textContent = '检索';
123	}
124	
125	function showMore(btn) {
126	  document.getElementById('more-results').style.display = '';
127	  btn.remove();
128	}
129	
130	function escapeHtml(s) { const d = document.createElement('div'); d.textContent = s == null ? '' : s; return d.innerHTML; }
131	document.getElementById('query-input').addEventListener('keydown', (e) => {
132	  if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); doSearch(); }
133	});
134	</script>
135	</body>
136	</html>
