118	      { name: '导入', type: 'bar', stack: 'total', data: daily.map(d => d.import || 0), itemStyle: { color: '#27ae60' } },
119	      { name: '分析', type: 'bar', stack: 'total', data: daily.map(d => d.analyze || 0), itemStyle: { color: '#e67e22' } },
