function getSourceHeader() {
  return window.examRadarSource ? window.examRadarSource() : 'real';
}

function renderContent(text) {
  return marked.parse(escapeHtml(text || ''));
}

// break a CJK/mixed topic name into short lines for the radar axis label
function axisLabel(item) {
  const words = item.topic_name.split('');
  const lines = [];
  for (let i = 0; i < words.length; i += 5) lines.push(words.slice(i, i + 5).join(''));
  return item.topic_id + '\n' + lines.join('\n');
}

function examQuestionHtml(q) {
  const content = q.content || '';
  const basis = (q.matched_terms && q.matched_terms.length)
    ? '命中考点词: ' + q.matched_terms.map(escapeHtml).join('、')
    : '纯语义相似度';
  const short = content.substring(0, 80);
  const truncated = content.length > 80;
  const id = 'q-text-' + q.question_no;
  return `<div class="result-item">
    <div class="meta">第${q.question_no}题 · ${q.points}分 · 语义 ${(q.similarity * 100).toFixed(1)}% · ${basis}</div>
    <div class="content">${escapeHtml(short)}${truncated ? '…' : ''}</div>
    ${truncated ? `<a href="javascript:void(0)" onclick="toggleQuestion('${id}')">展开全文</a>
      <div id="${id}" style="display:none" class="content">${escapeHtml(content)}</div>` : ''}
  </div>`;
}

function toggleQuestion(id) {
  const el = document.getElementById(id);
  const link = el.previousElementSibling;
  if (el.style.display === 'none') {
    el.style.display = '';
    link.textContent = '收起';
  } else {
    el.style.display = 'none';
    link.textContent = '展开全文';
  }
}

