function getSourceHeader() {
  return window.examRadarSource ? window.examRadarSource() : 'real';
}

function getTzName() {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC';
  } catch (e) {
    return 'UTC';
  }
}

function fmtStudyTime(minutes) {
  if (minutes === null || minutes === undefined) return '—';
  if (minutes < 60) return minutes + ' 分钟';
  const h = Math.floor(minutes / 60);
  const m = Math.round(minutes % 60);
  return m ? `${h} 小时 ${m} 分钟` : `${h} 小时`;
}

async function loadStats() {
  const cid = document.getElementById('course-id').value;
  const source = document.getElementById('source-select').value;
  const area = document.getElementById('stats-area');
  area.innerHTML = '<div class="card"><p>加载中...</p></div>';
  try {
    const r = await fetch(`/api/usage/stats?course_id=${encodeURIComponent(cid)}&source=${source}&tz=${encodeURIComponent(getTzName())}`);
    const d = await r.json();
    if (!r.ok) { area.innerHTML = `<div class="card"><span style="color:red">${escapeHtml(d.detail || '加载失败')}</span></div>`; return; }
    renderStats(d);
  } catch(e) {
    area.innerHTML = '<div class="card"><span style="color:red">加载失败</span></div>';
  }
}

function escapeHtml(s) { const d = document.createElement('div'); d.textContent = s == null ? '' : s; return d.innerHTML; }

