#!/usr/bin/env python3
"""Screenshot the t04 topic card (evidence markdown + question text)."""
import asyncio
import base64
import json
import subprocess
import sys
import time

import httpx
import websockets

CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
CDP_PORT = 9225
BASE = "http://127.0.0.1:18800"
SCRATCH = "/Users/wanderer/Project/oceanbase/powercontext-camp/.camp/wt/eco-qoder/qoder/.cache/scratch"


class CDP:
    def __init__(self, ws):
        self.ws = ws
        self._id = 0

    async def send(self, method, params=None):
        self._id += 1
        mid = self._id
        await self.ws.send(json.dumps({"id": mid, "method": method,
                                       "params": params or {}}))
        while True:
            data = json.loads(await self.ws.recv())
            if data.get("id") == mid:
                if "error" in data:
                    raise RuntimeError(f"{method}: {data['error']}")
                return data.get("result", {})

    async def evaluate(self, expr):
        r = await self.send("Runtime.evaluate", {
            "expression": expr, "returnByValue": True})
        if r.get("exceptionDetails"):
            raise RuntimeError(r["exceptionDetails"])
        return r.get("result", {}).get("value")

    async def screenshot(self, path):
        r = await self.send("Page.captureScreenshot", {"format": "png"})
        with open(path, "wb") as f:
            f.write(base64.b64decode(r["data"]))
        print(f"screenshot -> {path}")


async def main():
    proc = subprocess.Popen([
        CHROME, "--headless=new", f"--remote-debugging-port={CDP_PORT}",
        f"--user-data-dir={SCRATCH}/chrome-profile2", "--no-first-run",
        "--window-size=1440,1600", "about:blank",
    ], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    try:
        await asyncio.sleep(2)
        async with httpx.AsyncClient() as client:
            r = await client.put(
                f"http://127.0.0.1:{CDP_PORT}/json/new?"
                f"{BASE}/radar.html?source=auto", timeout=10)
            target = r.json()
        async with websockets.connect(target["webSocketDebuggerUrl"],
                                       max_size=50 * 1024 * 1024) as ws:
            cdp = CDP(ws)
            await cdp.send("Page.enable")
            await cdp.send("Page.navigate",
                           {"url": f"{BASE}/radar.html?source=auto"})
            await asyncio.sleep(2)
            await cdp.evaluate("loadLatest()")
            for _ in range(40):
                n = await cdp.evaluate(
                    "document.querySelectorAll('#results-area .card').length")
                if n and n >= 3:
                    break
                await asyncio.sleep(0.5)
            await asyncio.sleep(2)
            # a covered topic card with markdown evidence + a question
            await cdp.evaluate("""
              (() => {
                const cards = Array.from(document.querySelectorAll('#results-area .card'));
                const t04 = cards.find(c => c.querySelector('h2') &&
                                            c.querySelector('h2').textContent.includes('t04'));
                const link = Array.from(t04.querySelectorAll('a'))
                  .find(a => a.textContent === '展开全文');
                if (link) toggleQuestion(link.nextElementSibling.id);
                t04.scrollIntoView();
              })()
            """)
            await asyncio.sleep(1)
            await cdp.screenshot(f"{SCRATCH}/s05_radar_t04.png")
            # a covered topic card showing markdown-rendered evidence
            await cdp.evaluate("""
              (() => {
                const cards = Array.from(document.querySelectorAll('#results-area .card'));
                const t09 = cards.find(c => c.querySelector('h2') &&
                                            c.querySelector('h2').textContent.includes('t09'));
                const d = Array.from(t09.querySelectorAll('details'))
                  .find(x => x.querySelector('summary').textContent.includes('全部证据'));
                if (d) d.setAttribute('open', '');
                t09.scrollIntoView();
              })()
            """)
            await asyncio.sleep(1)
            await cdp.screenshot(f"{SCRATCH}/s05_radar_t09.png")
    finally:
        proc.terminate()
        proc.wait()


if __name__ == "__main__":
    asyncio.run(main())
